mapper.select:
SELECT 
FROM tbl_connected_account
WHERE id = #{id}
  AND user_id = #{userId}

mapper.update:
UPDATE tbl_connected_account
SET is_active = 0
WHERE id = #{id}
  AND user_id = #{userId}

UPDATE tbl_connected_account
SET sync_status      = #{syncStatus},
    last_sync_at     = #{lastSyncAt},
    sync_fail_reason = #{syncFailReason}
WHERE id = #{id}
  AND user_id = #{userId}

UPDATE tbl_connected_account
SET sync_status      = 'NORMAL',
    sync_fail_reason = NULL,
    balance          = #{balance},
    last_sync_at     = #{lastSyncAt}
WHERE id = #{id}
  AND user_id = #{userId}
